 552	/// Search for a surface by a 64 bit unique ID.
 553	pub fn findSurfaceByID(self: *const App, id: u64) ?*Surface {
 554	    for (self.surfaces.items) |v| {
 555	        const surface: *Surface = v.core();
 556	        if (surface.id == id) return surface;
 557	    }
 558	
 559	    return null;
 560	}
